@prefix ada: <https://ada.astromat.org/metadata/> .
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode [ a ada:XRDTabular ;
                    ada:geometry "Bragg-Brentano" ;
                    ada:sampleMount "flat plate" ;
                    ada:stepSize 2e-02 ;
                    ada:timePerStep 1e+00 ;
                    ada:wavelength 1.5406e+00 ] ;
            sh:resultMessage "XRD detail nodes must declare ada:componentType." ;
            sh:resultPath ada:componentType ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraintComponent sh:MinCountConstraintComponent ;
            sh:sourceShape [ sh:datatype xsd:string ;
                    sh:maxCount 1 ;
                    sh:message "XRD detail nodes must declare ada:componentType." ;
                    sh:minCount 1 ;
                    sh:path ada:componentType ] ] .
